\begin{proof}

 Let $\rho\in{DRP}_n$ be as expressed in \eqref{2}, where $b(\rho)=r$ and $h(\rho)=p$. Moreover, let $w=\min(\mathop{\rm Dom}\nolimits \, \rho)$. Note that $p\leq w\leq n - p + 1$, from the proof of Lemma \ref{rev},   and for all $x_i \in \mathop{\rm Dom}\nolimits \, \rho$ and $a_j \in \mathop{\rm Im}\nolimits \, \rho$, we have $ a_j\leq x_i$. To count the number of $\rho\in{DRP}_n$, we first choose the domain elements. Now, since $w\in \mathop{\rm Dom}\nolimits \, \rho$, we can choose the remaining $r-1$ elements from $[n]\setminus\{1,\ldots,w\}$, i.e., in ${n - w \choose r - 1}$ ways. Next, we partition the $r$ elements in the domain into $p$  convex (modulo $\mathop{\rm Dom}\nolimits \, \rho$) blocks in ${r - 1 \choose p - 1}$ ways. Then, we can choose the $p$ images from the set $\{1,\ldots,w\}$  in ${w \choose p}$ ways. Finally, taking the sum of the product: ${n-w\choose r-1} {r-1\choose p-1} {w\choose p}$, from $w=p$ to $w=n-p+1$ produces
\begin{align*}  F(n,r,p)&=\sum_{w=p}^{n-p+1} {n-w\choose r-1} {r-1\choose p-1} {w\choose p}\\&=
{r-1\choose p-1}\sum_{w=p}^{n-p+1} {n-w\choose r-1}  {w\choose p}
\\&=
{r-1 \choose p-1} {n+1 \choose r+p}, \quad (\text{by Lemma \ref{id}})
\end{align*}
\noindent as postulated.

\end{proof}
\bigskip

\begin{corollary}\label{co}

The number of elements in ${DRP}_n$ of a fixed height $1\le p\le \lceil\frac{n}{2}\rceil$ is
\begin{equation}\label{coo} F(n,p)= \sum_{r=p}^{n-p+1}{r-1 \choose p-1} {n+1 \choose r+p}.\end{equation}
\end{corollary}
\begin{proof}
 We get the number by varying the width within the possible range which is $p\leq r\leq n-p+1$.
\end{proof}

We will now state the following lemma.
\begin{lemma} Let $F(n,p)$ be as in  \eqref{coo} and let $a_{n} = \sum\limits_{p=2}^{\lceil\frac{n}{2} \rceil} F(n, p)$. Then
\[
a_{n} =  \sum\limits_{p=2}^{\lceil\frac{n}{2} \rceil}  \sum_{r=p}^{n-p+1}  {r-1 \choose p-1} {n+1 \choose r+p}.
\]
\end{lemma}

At this point, we present the following result.

\begin{theorem} Let $s_{n}$ be as defined in \eqref{nums}. Then $|\mathcal{DORP}_{n}|=s_{n}+a_{n}$.
\end{theorem}
\begin{proof} Notice that, as in \eqref{qn2}, $\mathcal{DORP}_{n} = \mathcal{LS}_{n} \cup DRP_{n}$. However, elements of exactly height $1$ are both isotone and antitone maps, so  $$|\mathcal{LS}_{n} \cap DRP_{n}|=F(n,1).$$ \noindent Thus,  $$|\mathcal{DORP}_{n}| =|\mathcal{LS}_{n} \cup DRP_{n}|= |\mathcal{LS}_{n}|+| DRP_{n}|-| \mathcal{LS}_{n} \cap DRP_{n}|,$$ \noindent and therefore
\[|\mathcal{DORP}_{n}| =s_{n}+\sum\limits_{p=1}^{\lceil\frac{n}{2} \rceil} {F(n, p)}-F(n,1)=s_{n}+ F(n,1)+\sum\limits_{p=2}^{\lceil\frac{n}{2} \rceil} {F(n, p)}-F(n,1)=s_{n}+a_{n},\] as required.
\end{proof}

\begin{remark}
 It is  significant to highlight that the triangle of numbers $F(n,\, p)$ and the sequences $a_{n}$ and $s_{n}+a_{n}$ are not yet recorded in The Online Encyclopedia of Integer Sequences \cite{slone}.
\end{remark}

